command:
set -euo pipefail
git rev-parse HEAD > "$RUNNER_TEMP/p2-combined/source-sha.txt"
git rev-parse 'HEAD^{tree}' > "$RUNNER_TEMP/p2-combined/source-tree.txt"
docker inspect --format '{{.Config.Image}} {{.Image}}' "${{ job.services.postgres.id }}" "${{ job.services.mongodb.id }}" > "$RUNNER_TEMP/p2-combined/service-images.txt"
python - <<'PY' > "$RUNNER_TEMP/p2-combined/postgres-identity.json"
import psycopg, json
with psycopg.connect('postgresql://postgres:postgres@localhost:5432/p2a') as c:
    name, version = c.execute('SELECT current_database(), version()').fetchone()
    assert name == 'p2a'
    print(json.dumps(dict(database=name, version=version)))
PY
(cd backend && node --input-type=module <<'JS') > "$RUNNER_TEMP/p2-combined/mongo-identity.json"
import {MongoClient} from 'mongodb';
const c = new MongoClient(process.env.MONGODB_URI);
await c.connect();
const db = c.db();
if (db.databaseName !== 'p2a') throw new Error('Wrong isolated database');
console.log(JSON.stringify({database:db.databaseName,version:(await db.admin().serverInfo()).version}));
await c.close();
JS
printf 'LLM_PROVIDER=fake\nEMBEDDING_PROVIDER=fake\nSERVICE_AUTH_DISABLED=false\nNo paid-provider secrets supplied\n' > "$RUNNER_TEMP/p2-combined/provider-config.txt"
